_SRC = os.path.join(os.path.dirname(os.path.abspath(__file__)), "ch24-page", "sources") + os.sep
_FILL = {"@WHEEL@": _SRC + "sen0414_ch24_pyttsx3_2_99_wheel_v1_0_0.whl", "@UTILS@": _SRC + "sen0414_ch24_whisper_utils_20250625_v1_0_0.py",
         "@INIT@": _SRC + "sen0414_ch24_whisper_init_20250625_v1_0_0.txt", "@TOK@": _SRC + "sen0414_ch24_whisper_tokenizer_20250625_v1_0_0.txt",
         "@AUD@": _SRC + "sen0414_ch24_whisper_audio_20250625_v1_0_0.txt", "@TRN@": _SRC + "sen0414_ch24_whisper_transcribe_20250625_v1_0_0.txt",
         "@README@": _SRC + "sen0414_ch24_whisper_README_20250625_v1_0_0.txt"}
def _fill(code):
    for k, v in _FILL.items():
        code = code.replace(k, v)
    return code
