 ["my own timestamp formulas equal Whisper's format_timestamp", "import importlib.util\nspec = importlib.util.spec_from_file_location('whisper_utils', '@UTILS@')\nwu = importlib.util.module_from_spec(spec); spec.loader.exec_module(wu)\ndef srt(seconds):\n    ms = round(seconds * 1000.0)\n    return '%02d:%02d:%02d,%03d' % (ms // 3600000, ms % 3600000 // 60000, ms % 60000 // 1000, ms % 1000)\ndef vtt(seconds):\n    ms = round(seconds * 1000.0)\n    h = '%02d:' % (ms // 3600000) if ms >= 3600000 else ''\n    return '%s%02d:%02d.%03d' % (h, ms % 3600000 // 60000, ms % 60000 // 1000, ms % 1000)\nsamples = [0, 0.001, 5.64, 14.96, 59.9996, 61.5, 3599.999, 3600, 3661.5, 86399.123]\nprint(all(srt(s) == wu.format_timestamp(s, True, ',') for s in samples), all(vtt(s) == wu.format_timestamp(s) for s in samples))\nprint(srt(5.64), vtt(5.64), vtt(3661.5), srt(86399.123))\n", 'True True\n00:00:05,640 00:05.640 01:01:01.500 23:59:59,123'],
 ['word timestamps let the writer break subtitles by word count or by line width, options the chapter does not cover', "import importlib.util, os, tempfile\nspec = importlib.util.spec_from_file_location('whisper_utils', '@UTILS@')\nwu = importlib.util.module_from_spec(spec); spec.loader.exec_module(wu)\nwords = [(' one', 0.0, 0.5), (' two', 0.5, 1.0), (' three', 1.0, 1.6), (' four', 1.6, 2.0), (' five', 2.0, 2.4)]\nresult = {'text': ' one two three four five', 'segments': [{'start': 0.0, 'end': 2.4, 'text': ' one two three four five',\n          'words': [{'word': w, 'start': s, 'end': e} for w, s, e in words]}]}\nfor options in ({}, {'max_words_per_line': 2}, {'max_line_width': 10, 'max_line_count': 2}):\n    with tempfile.TemporaryDirectory() as d:\n        wu.get_writer('srt', d)(result, 'audio', options)\n        print(options, repr(open(os.path.join(d, 'audio.srt'), encoding='utf-8').read()))\n", "{} '1\\n00:00:00,000 --> 00:00:02,400\\none two three four five\\n\\n'\n{'max_words_per_line': 2} '1\\n00:00:00,000 --> 00:00:01,000\\none two\\n\\n2\\n00:00:01,000 --> 00:00:02,000\\nthree four\\n\\n3\\n00:00:02,000 --> 00:00:02,400\\nfive\\n\\n'\n{'max_line_width': 10, 'max_line_count': 2} '1\\n00:00:00,000 --> 00:00:02,000\\none two\\nthree four\\n\\n2\\n00:00:02,000 --> 00:00:02,400\\nfive\\n\\n'"],
 ['the model names Whisper 20250625 accepts, and the default of its command line', 'import ast, re\nsrc = open(\'@INIT@\', encoding=\'utf-8\').read()\nmodels = None\nfor node in ast.parse(src).body:\n    if isinstance(node, ast.Assign) and getattr(node.targets[0], \'id\', \'\') == \'_MODELS\':\n        models = ast.literal_eval(node.value)\nprint(len(models), list(models))\nprint([m in models for m in (\'tiny\', \'base\', \'small\', \'medium\', \'large-v3\')])\nprint(models[\'large\'] == models[\'large-v3\'], models[\'turbo\'] == models[\'large-v3-turbo\'])\nprint(re.findall(r\'"--model", default="(\\w+)"\', open(\'@TRN@\', encoding=\'utf-8\').read()))\n', "14 ['tiny.en', 'tiny', 'base.en', 'base', 'small.en', 'small', 'medium.en', 'medium', 'large-v1', 'large-v2', 'large-v3', 'large', 'large-v3-turbo', 'turbo']\n[True, True, True, True, True]\nTrue True\n['turbo']"],
 ["Whisper's language names: how many, and whether the chapter's 'English' is accepted", "import ast\nsrc = open('@TOK@', encoding='utf-8').read()\ntree = ast.parse(src)\nlangs = next(ast.literal_eval(n.value) for n in tree.body if isinstance(n, ast.Assign) and getattr(n.targets[0], 'id', '') == 'LANGUAGES')\nprint(len(langs), langs['en'], langs['tr'])\nnames = {v: k for k, v in langs.items()}\nprint('English'.lower() in names, names['english'])\nprint('get_tokenizer lowercases the name:', 'language = language.lower()' in src)\n", '100 english turkish\nTrue en\nget_tokenizer lowercases the name: True'],
 ['what Whisper does to the audio file: it calls ffmpeg for 16 kHz mono samples, and transcribe() returns text, segments and language', 'import ast, re\nsrc = open(\'@AUD@\', encoding=\'utf-8\').read()\nprint(re.findall(r\'^SAMPLE_RATE = (\\d+)\', src, re.M), \'"ffmpeg"\' in src, \'"-ar"\' in src, \'"-ac", "1"\' in src, \'Requires the ffmpeg CLI in PATH\' in src)\ntsrc = open(\'@TRN@\', encoding=\'utf-8\').read()\ntree = ast.parse(tsrc)\nfn = next(n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == \'transcribe\')\nret = [n for n in ast.walk(fn) if isinstance(n, ast.Return) and isinstance(n.value, ast.Call) and getattr(n.value.func, \'id\', \'\') == \'dict\'][-1]\nprint([k.arg for k in ret.value.keywords])\n', "['16000'] True True True True\n['text', 'segments', 'language']"],
 ['the output template of the chapter and glob find the downloaded file', "import os, tempfile\nfrom pathlib import Path\nprint('downloaded_content.%(ext)s' % {'ext': 'm4a'})\nwith tempfile.TemporaryDirectory() as d:\n    os.chdir(d)\n    for name in ('downloaded_content.m4a', 'notes.txt', 'downloaded_content_old.mp3'):\n        Path(name).write_text('x')\n    matching_filenames = list(Path().glob('downloaded_content.*'))\n    downloaded_filename = str(matching_filenames[0])\n    print(len(matching_filenames), repr(downloaded_filename))\n    os.chdir('/')\n", "downloaded_content.m4a\n1 'downloaded_content.m4a'"],
 ['the metadata file of the chapter: JSON written with encoding utf-8 and read back', "import json, os, tempfile\ninfo = {'title': 'Beyond the Basic Stuff with Python - Al Sweigart - Part 1', 'duration': 3600, 'id': 'kSrnLbioN6w'}\nwith tempfile.TemporaryDirectory() as d:\n    path = os.path.join(d, 'metadata.json')\n    with open(path, 'w', encoding='utf-8') as json_file:\n        json_file.write(json.dumps(info))\n    back = json.load(open(path, encoding='utf-8'))\nprint(back == info, sorted(back), back['title'])\n", "True ['duration', 'id', 'title'] Beyond the Basic Stuff with Python - Al Sweigart - Part 1"],
 ['hello_tts.py of the chapter with a recording stand-in for the engine and a scripted answer', "import io, sys\nclass Recorder:\n    def __init__(self): self.said = []; self.pending = []\n    def say(self, text): self.pending.append(text)\n    def runAndWait(self): self.said += self.pending; self.pending = []\nengine = Recorder()\nsys.stdin = io.StringIO('great\\n')\nengine.say('Hello. How are you doing?')\nengine.runAndWait()\nfeeling = input('>')\nengine.say('Yes. I am feeling ' + feeling + ' as well.')\nengine.runAndWait()\nprint(engine.said)\n", ">['Hello. How are you doing?', 'Yes. I am feeling great as well.']"],
 ['practice program: voice for guess the number, with a recording stand-in for the engine', "class Recorder:\n    def __init__(self): self.said = []\n    def say(self, text): self.said.append(text)\n    def runAndWait(self): pass\nengine = Recorder()\ndef speak(text):\n    print(text)\n    engine.say(text)\n    engine.runAndWait()\ndef play(secret, guesses):\n    speak('I am thinking of a number between 1 and 20.')\n    for n, guess in enumerate(guesses, 1):\n        if guess < secret:\n            speak('Your guess, %d, is too low.' % guess)\n        elif guess > secret:\n            speak('Your guess, %d, is too high.' % guess)\n        else:\n            speak('Good job! You guessed my number in %d guesses!' % n)\n            break\nplay(14, [10, 18, 14])\nprint(engine.said == ['I am thinking of a number between 1 and 20.', 'Your guess, 10, is too low.', 'Your guess, 18, is too high.', 'Good job! You guessed my number in 3 guesses!'])\n", 'I am thinking of a number between 1 and 20.\nYour guess, 10, is too low.\nYour guess, 18, is too high.\nGood job! You guessed my number in 3 guesses!\nTrue'],
 ['practice program: the lyrics of 99 bottles of beer, started at 3', "def verses(start):\n    lines = []\n    for n in range(start, 0, -1):\n        now = '%d bottle%s' % (n, '' if n == 1 else 's')\n        left = 'No more bottles' if n == 1 else '%d bottle%s' % (n - 1, '' if n == 2 else 's')\n        lines += [now + ' of beer on the wall,', now + ' of beer,', 'Take one down, pass it around,', left + ' of beer on the wall.', '']\n    return lines\nprint('\\n'.join(verses(3)))\n", '3 bottles of beer on the wall,\n3 bottles of beer,\nTake one down, pass it around,\n2 bottles of beer on the wall.\n\n2 bottles of beer on the wall,\n2 bottles of beer,\nTake one down, pass it around,\n1 bottle of beer on the wall.\n\n1 bottle of beer on the wall,\n1 bottle of beer,\nTake one down, pass it around,\nNo more bottles of beer on the wall.'],
 ['practice program: the YouTube transcriber as glue, with stand-ins for yt-dlp and Whisper', "def transcribe_all(urls, download, transcribe, write):\n    done = []\n    for url in urls:\n        audio = download(url)\n        result = transcribe(audio)\n        done.append(write(result, audio))\n    return done\nfake_download = lambda url: 'downloaded_' + url.rsplit('=', 1)[-1] + '.m4a'\nfake_transcribe = lambda audio: {'text': 'stand-in text for ' + audio, 'segments': [{'start': 0.0, 'end': 1.0, 'text': ' stand-in'}]}\ndef fake_write(result, audio):\n    stem = audio.rsplit('.', 1)[0]\n    return stem + '.srt: ' + '1\\n00:00:00,000 --> 00:00:01,000\\n' + result['segments'][0]['text'].strip()\nfor line in transcribe_all(['https://example.test/watch?v=aaa', 'https://example.test/watch?v=bbb'], fake_download, fake_transcribe, fake_write):\n    print(repr(line))\n", "'downloaded_aaa.srt: 1\\n00:00:00,000 --> 00:00:01,000\\nstand-in'\n'downloaded_bbb.srt: 1\\n00:00:00,000 --> 00:00:01,000\\nstand-in'"],
